package io.github.chachen.platform.system.service;
import com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper; import io.github.chachen.platform.system.entity.SysMenu; import io.github.chachen.platform.system.mapper.SysMenuMapper; import java.util.*;
public class MenuService { private final SysMenuMapper mapper; public MenuService(SysMenuMapper m){mapper=m;} public List<MenuView> list(){return mapper.selectList(new LambdaQueryWrapper<SysMenu>().orderByAsc(SysMenu::getSort)).stream().map(m->new MenuView(m.getId(),m.getParentId(),m.getName(),m.getPath(),m.getPermission(),m.getStatus(),m.getSort())).toList();} public void create(Long parentId,String name,String path,String permission,Integer sort){var m=new SysMenu();m.setParentId(parentId==null?0L:parentId);m.setName(name);m.setPath(path);m.setPermission(permission);m.setStatus(1);m.setSort(sort==null?0:sort);mapper.insert(m);} public record MenuView(Long id,Long parentId,String name,String path,String permission,Integer status,Integer sort){} }
